<section class="components-page form-elements-page">
  <div class="row g-4">
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Basic File Input</h5></div><div class="card-body form-stack"><div><label class="form-label" for="formFile">Default file input example</label><input class="form-control" type="file" id="formFile"></div><div><label class="form-label" for="formFileMultiple">Multiple files input example</label><input class="form-control" type="file" id="formFileMultiple" multiple></div><div><label class="form-label" for="formFileDisabled">Disabled file input example</label><input class="form-control" type="file" id="formFileDisabled" disabled></div><div><label class="form-label" for="formFileSm">Small file input example</label><input class="form-control form-control-sm" id="formFileSm" type="file"></div><div><label class="form-label" for="formFileLg">Large file input example</label><input class="form-control form-control-lg" id="formFileLg" type="file"></div></div></div></div>
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Dropzone</h5></div><div class="card-body"><label class="upload-dropzone" for="dropzoneInput" data-upload-zone><i class="bi bi-cloud-arrow-up"></i><span>Drop files here or click to upload</span><small>Upload up to 5 files. Images, PDFs, and documents are accepted.</small><input id="dropzoneInput" type="file" multiple hidden></label><div class="upload-list" data-upload-list></div></div></div></div>
  </div>
  <div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Image Preview</h5></div><div class="card-body"><label class="upload-dropzone upload-preview-zone" for="imagePreviewInput" data-upload-zone><i class="bi bi-images"></i><span>Choose image preview</span><small>Selected image names are shown below for static-friendly review.</small><input id="imagePreviewInput" type="file" accept="image/*" multiple hidden></label><div class="upload-list upload-preview-list" data-upload-list></div></div></div>
</section>